type Detail={type:string;id?:string}|null;
const money=(n:number)=>(n<0?"-₹":"₹")+Math.round(Math.abs(n)).toLocaleString("en-IN");
const cash=(n:number|null)=>n===null?"—":n<0?"-"+cash(-n):n>=10000000?`₹${(n/10000000).toFixed(2)} Cr`:n>=100000?`₹${(n/100000).toFixed(2)} L`:money(n);
const num=(n:number)=>Math.round(n).toLocaleString("en-IN");
const pct=(n:number|null)=>n===null?"Not available":`${(n*100).toFixed(1)}%`;
const time=()=>new Date().toLocaleString("en-IN",{timeZone:"Asia/Kolkata",day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"});
function download(name:string,content:string,type="text/csv;charset=utf-8"){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast.success("Report downloaded")}
function csv(rows:(string|number)[][]){return rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(",")).join("\n")}
function parseCsv(text:string){const rows:string[][]=[];let row:string[]=[],cell="",quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"'){quoted=!quoted}else if(ch===','&&!quoted){row.push(cell.trim());cell=""}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(v=>v!==""))rows.push(row);row=[];cell=""}else cell+=ch}if(cell!==""||row.length){row.push(cell.trim());if(row.some(v=>v!==""))rows.push(row)}return rows}
const csvFields=[{id:"date",label:"Date",required:true},{id:"storeCode",label:"SAP / store code",required:true},{id:"revenue",label:"Net sales / revenue",required:true},{id:"promise",label:"Sales promise",required:false},{id:"bills",label:"Bills / transactions",required:false},{id:"newCustomers",label:"New customers",required:false},{id:"existingCustomers",label:"Existing customers",required:false},{id:"footfall",label:"Jarvis footfall",required:false}] as const;
function SimpleTable({heads,rows}:{heads:string[];rows:React.ReactNode[][]}){return <div className="overflow-auto"><table className="workspace-plain-table"><thead><tr>{heads.map(h=><th key={h} className={/Revenue|Sales|Spend|Cost|NPS|ROMI|ROAS|Footfall|Orders|Bills/.test(h)?"n":""}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j} className={/Revenue|Sales|Spend|Cost|NPS|ROMI|ROAS|Footfall|Orders|Bills/.test(heads[j])?"n":""}>{v}</td>)}</tr>)}</tbody></table></div>}
function Box({title,sub,children,action}:{title:string;sub?:string;children:React.ReactNode;action?:React.ReactNode}){return <Card className="gap-0 py-0 shadow-none mb-5"><div className="table-heading"><div><h2 className="section-title">{title}</h2>{sub&&<p className="meta-copy mt-1">{sub}</p>}</div>{action}</div><div className="card-body">{children}</div></Card>}
function Metric({label,value,sub,onClick}:{label:string;value:string;sub?:string;onClick?:()=>void}){return <Card className={`workspace-card ${onClick?"workspace-click":""}`} onClick={onClick} role={onClick?"button":undefined} tabIndex={onClick?0:undefined} onKeyDown={e=>{if(onClick&&e.key==="Enter")onClick()}}><div className="muted-copy">{label}</div><div className="workspace-stat">{value}</div><div className="meta-copy">{sub}</div></Card>}
const retailNav=[{group:"RETAIL MARKETING",items:[["overview","Overview",LayoutDashboard],["activities","Campaigns & activities",Megaphone],["stores","Stores",Store],["customers","Customers & NPS",Users],["reports","Reports",FileText],["connections","Data sources",Link2]]}] as const;
const romiNav=[{group:"ROMI DASHBOARD",items:[["overview","Overview",LayoutDashboard],["investment","Investment",Wallet],["outcomes","Outcomes & incrementality",BarChart3],["recommendations","Recommendations",ClipboardCheck],["reports","Reports",FileText],["method","Method & acceptance",CheckCircle2]]}] as const;
function Frame({title,view,onView,nav,periodLength,onPeriod,onAgent,children}:{title:string;view:string;onView:(v:string)=>void;nav:typeof retailNav|typeof romiNav;periodLength:number;onPeriod:(n:number)=>void;onAgent:()=>void;children:React.ReactNode}){const label=nav.flatMap(g=>g.items).find(i=>i[0]===view)?.[1]||"Overview";return <SidebarProvider><div className="workspace-frame flex w-full"><Sidebar collapsible="offcanvas"><SidebarHeader className="p-5 border-b"><div className="sidebar-brand flex gap-2 items-center"><span className="size-8 grid place-items-center rounded-lg bg-accent"><BarChart3 className="size-5"/></span>{title}</div></SidebarHeader><SidebarContent>{nav.map(g=><SidebarGroup key={g.group}><SidebarGroupLabel className="nav-label">{g.group}</SidebarGroupLabel><SidebarGroupContent><SidebarMenu>{g.items.map(([id,name,Icon])=><SidebarMenuItem key={id}><SidebarMenuButton isActive={view===id} onClick={()=>onView(id)} tooltip={name}><Icon className="size-4"/><span>{name}</span></SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu></SidebarGroupContent></SidebarGroup>)}</SidebarContent><SidebarFooter className="p-4 border-t"><div className="next-modules"><div className="eyebrow text-primary">BLACKBERRYS</div><p className="meta-copy">SOW scope review · synthetic data</p></div></SidebarFooter></Sidebar><SidebarInset className="app-main"><header className="topbar"><div className="flex gap-3 items-center"><SidebarTrigger/><span className="font-semibold">{label}</span></div><div className="flex items-center gap-2"><Badge className="status status-amber">DEMO DATA</Badge><Button variant="outline" onClick={onAgent}><Sparkles/> Ask agent</Button></div></header><main className="page-content"><div className="page-header"><div><h1>{label}</h1><p className="page-description">{title} · linked evidence and decisions</p></div><Select value={String(periodLength)} onValueChange={v=>onPeriod(Number(v))}><SelectTrigger className="w-[220px] bg-white" aria-label="Reporting period"><CalendarDays className="size-4"/><SelectValue/></SelectTrigger><SelectContent><SelectItem value="7">22–28 Sep 2026 · 7 days</SelectItem><SelectItem value="14">15–28 Sep 2026 · 14 days</SelectItem></SelectContent></Select></div><p className="meta-copy mb-5">Illustrative source records through 28 Sep 2026 · No live Blackberrys data connected</p>{children}</main></SidebarInset></div></SidebarProvider>}
const initialRetailActions:ActionRecord[]=[{id:"RA-01",activityId:"ACT-01",title:"Review repeating Delhi wedding edit",priority:"High",owner:"Retail Marketing",status:"Proposed",confidence:"Medium",impact:"Test whether the measured store uplift repeats in another comparable store",history:[]},{id:"RA-02",activityId:"ACT-02",title:"Test the Mumbai influencer format again",priority:"Medium",owner:"Brand Marketing",status:"Proposed",confidence:"Medium",impact:"Check repeatable incremental store revenue against full activity cost",history:[]},{id:"RA-03",activityId:"ACT-03",title:"Wait for completed activity and footfall coverage",priority:"Urgent",owner:"Retail Marketing",status:"Proposed",confidence:"High",impact:"Prevents an unsupported incrementality claim; Jarvis is unavailable for this store",history:[]}];

