  const [view,setView]=useState("overview"),[n,setN]=useState(7),[detail,setDetail]=useState<Detail>(null),[activities,setActivities]=useState<ActivityRecord[]>(()=>structuredClone(initialActivities) as ActivityRecord[]),[actions,setActions]=useState<ActionRecord[]>(initialRetailActions),[query,setQuery]=useState(""),[city,setCity]=useState("All"),[tier,setTier]=useState("All"),[cohort,setCohort]=useState("All"),[channel,setChannel]=useState("All"),[report,setReport]=useState(false),[agentQuery,setAgentQuery]=useState(""),[form,setForm]=useState({name:"",objective:"",type:"Mall branding",owner:"Retail Marketing",start:"2026-09-22",end:"2026-09-28",storeCode:stores[0].code,costType:"Mall branding",planned:"",actual:"",asset:""}),[extra,setExtra]=useState({type:"Production",planned:"",actual:""}),[measured,setMeasured]=useState(""),[csvSource,setCsvSource]=useState<{name:string;headers:string[];rows:string[][]}|null>(null),[csvMapping,setCsvMapping]=useState<Record<string,string>>({}),[csvSaved,setCsvSaved]=useState<{name:string;rows:Record<string,string>[]}|null>(null),[csvError,setCsvError]=useState("");
  const p=period(n),all=rwithin(pos,p),sales=rsum(all,"revenue"),bills=rsum(all,"bills"),footfall=rsum(all.filter(r=>r.footfall!==null),"footfall"),newCustomers=rsum(all,"newCustomers"),active=activities.filter(a=>a.start<=p.end&&a.end>=p.start),spend=rsum(active.map(a=>({cost:activityCost(a)})),"cost");
