  const store=(code:string)=>stores.find(s=>s.code===code);
  const updateAction=(id:string,status:string)=>setActions(list=>list.map(a=>a.id===id?{...a,status,history:[...a.history,{at:time(),event:status}]}:a));
  async function loadCsv(file?:File){if(!file)return;setCsvError("");try{const parsed=parseCsv(await file.text());if(parsed.length<2)throw new Error("CSV needs a header row and at least one data row.");const headers=parsed[0],norm=(s:string)=>s.toLowerCase().replace(/[^a-z0-9]/g,"");const aliases:Record<string,string[]>={date:["date","businessdate","transactiondate"],storeCode:["storecode","sapcode","sapstorecode","storeid"],revenue:["netsales","netrevenue","revenue","sales"],promise:["promise","salestarget","target"],bills:["bills","transactions","orders"],newCustomers:["newcustomers","firsttimecustomers"],existingCustomers:["existingcustomers","returningcustomers"],footfall:["footfall","walkins","walkins"]};const map=Object.fromEntries(csvFields.map(f=>[f.id,headers.find(h=>aliases[f.id].includes(norm(h)))||""]));setCsvSource({name:file.name,headers,rows:parsed.slice(1)});setCsvMapping(map)}catch(e){setCsvError(e instanceof Error?e.message:"Could not read this CSV.")}}
  const arrangedRows=(csvSource?.rows||[]).map(row=>Object.fromEntries(csvFields.filter(f=>csvMapping[f.id]).map(f=>[f.id,row[csvSource!.headers.indexOf(csvMapping[f.id])]||""])));
  function saveCsvImport(){const required=csvFields.filter(f=>f.required);if(!csvSource||required.some(f=>!csvMapping[f.id])){setCsvError("Map Date, SAP / store code and Net sales / revenue before importing.");return}const valid=arrangedRows.filter(r=>r.date&&r.storeCode&&r.revenue&&Number.isFinite(Number(r.revenue.replace(/[₹, ]/g,""))));if(!valid.length){setCsvError("No valid rows found. Check the required mapped values and revenue column.");return}const value={name:csvSource.name,rows:valid.map(r=>({...r,revenue:String(Math.round(Number(r.revenue.replace(/[₹, ]/g,""))))}))};setCsvSaved(value);localStorage.setItem("bb-retail-csv-upload-v1",JSON.stringify(value));setCsvError("");toast.success(`${valid.length} CSV rows staged and mapped`)}
  const metrics=<div className="workspace-kpis five"><Metric label="Activities in period" value={num(active.length)} sub="Activity and spend register" onClick={()=>setView("activities")}/><Metric label="Actual activity cost" value={cash(spend)} sub="Across linked activities" onClick={()=>setView("activities")}/><Metric label="POS store sales" value={cash(sales)} sub="All demo stores" onClick={()=>setView("stores")}/><Metric label="New store customers" value={num(newCustomers)} sub="POS new-customer flag" onClick={()=>setView("customers")}/><Metric label="Jarvis walk-ins" value={num(footfall)} sub="Four covered stores only" onClick={()=>setView("stores")}/></div>;
