  const overview=<>{metrics}<div className="workspace-columns"><Box title="Store and activity signals" sub="Observed change with the matching control alongside"><div className="space-y-3">{active.map(activity=>{const r=activityResult(activity);return <button key={activity.id} className="workspace-action text-left w-full hover:border-primary" onClick={()=>open("activity",activity.id)}><div className="workspace-row"><strong>{activity.name}</strong><span className="workspace-tag">{activity.status}</span></div><p>Participating store sales: {cash(r.observed)}. Control comparison: {r.incremental===null?"Not yet assessable":`${cash(r?.incremental??null)} incremental revenue in this synthetic matched comparison`}.</p><span className="workspace-inline">{activity.storeCodes.join(", ")} · spend {cash(r.spend)} · open evidence</span></button>})}</div></Box><Box title="Store funnel and experience" sub="Jarvis where available; POS and NPS elsewhere"><div className="workspace-rail"><div>Walk-ins (covered)<b>{num(footfall)}</b></div><div>POS bills<b>{num(bills)}</b></div><div>Store sales<b>{cash(sales)}</b></div><div>New customers<b>{num(newCustomers)}</b></div></div><p className="workspace-summary">Bengaluru stores have no Jarvis feed in this sample. Their sales and customers remain visible, with no inferred footfall or conversion rate.</p><Button variant="outline" onClick={()=>setView("stores")}>Open stores</Button></Box></div>{actionList}</>;
